bool OpenGLESApi::complete()const noexcept{return Clear&&ClearColor&&Viewport&&Enable&&Disable&&DepthFunc&&BlendFunc&&CreateShader&&ShaderSource&&CompileShader&&GetShaderiv&&GetShaderInfoLog&&DeleteShader&&CreateProgram&&AttachShader&&LinkProgram&&GetProgramiv&&GetProgramInfoLog&&UseProgram&&DeleteProgram&&GetUniformLocation&&UniformMatrix4fv&&Uniform3f&&Uniform4f&&Uniform1f&&Uniform1i&&GenBuffers&&BindBuffer&&BufferData&&DeleteBuffers&&GenVertexArrays&&BindVertexArray&&DeleteVertexArrays&&EnableVertexAttribArray&&VertexAttribPointer&&DrawElements;}
bool OpenGLESRenderer::ready()const noexcept{return api_.complete()&&program_!=0&&skinned_program_!=0;}
bool OpenGLESRenderer::compile_shader(GlEnum type,const char*source,GlUInt&shader,std::string&error){shader=api_.CreateShader(type);if(!shader){error="OpenGL ES glCreateShader failed";return false;}const GlInt len=static_cast<GlInt>(std::strlen(source));api_.ShaderSource(shader,1,&source,&len);api_.CompileShader(shader);GlInt ok=0;api_.GetShaderiv(shader,GL_COMPILE_STATUS,&ok);if(!ok){GlInt n=0;api_.GetShaderiv(shader,GL_INFO_LOG_LENGTH,&n);std::vector<char>log(static_cast<std::size_t>(std::max(1,n)),0);GlInt written=0;api_.GetShaderInfoLog(shader,n,&written,log.data());error.assign(log.data(),static_cast<std::size_t>(std::max(0,written)));api_.DeleteShader(shader);shader=0;return false;}return true;}
bool OpenGLESRenderer::link_program(const char*vs_source,GlUInt vshader,const char*fs_source,GlUInt&program,std::string&error){GlUInt fs=0;if(!compile_shader(GL_FRAGMENT_SHADER,fs_source,fs,error))return false;program=api_.CreateProgram();if(!program){api_.DeleteShader(fs);error="OpenGL ES glCreateProgram failed";return false;}api_.AttachShader(program,vshader);api_.AttachShader(program,fs);api_.LinkProgram(program);api_.DeleteShader(vshader);api_.DeleteShader(fs);GlInt ok=0;api_.GetProgramiv(program,GL_LINK_STATUS,&ok);if(!ok){GlInt n=0;api_.GetProgramiv(program,GL_INFO_LOG_LENGTH,&n);std::vector<char>log(static_cast<std::size_t>(std::max(1,n)),0);GlInt written=0;api_.GetProgramInfoLog(program,n,&written,log.data());error.assign(log.data(),static_cast<std::size_t>(std::max(0,written)));api_.DeleteProgram(program);program=0;return false;}return true;}
bool OpenGLESRenderer::ensure_programs(std::string&error){if(program_&&skinned_program_)return true;if(!api_.complete()){error="OpenGL ES API table is incomplete";return false;}const auto mobile=make_mobile_pbr_shader();const auto skinned=make_mobile_skinned_pbr_shader();GlUInt vs=0;if(!compile_shader(GL_VERTEX_SHADER,mobile.vertex_source.c_str(),vs,error))return false;if(!link_program(mobile.vertex_source.c_str(),vs,mobile.fragment_source.c_str(),program_,error))return false;GlUInt svs=0;if(!compile_shader(GL_VERTEX_SHADER,skinned.vertex_source.c_str(),svs,error)){release();return false;}if(!link_program(skinned.vertex_source.c_str(),svs,skinned.fragment_source.c_str(),skinned_program_,error)){release();return false;}
u_vp_=api_.GetUniformLocation(program_,"u_view_projection");u_model_=api_.GetUniformLocation(program_,"u_model");u_camera_=api_.GetUniformLocation(program_,"u_camera_position");u_ambient_=api_.GetUniformLocation(program_,"u_ambient_intensity");u_base_=api_.GetUniformLocation(program_,"u_base_roughness");u_metal_=api_.GetUniformLocation(program_,"u_metal_specular");u_emission_=api_.GetUniformLocation(program_,"u_emission_opacity");u_light_dir_=api_.GetUniformLocation(program_,"u_light_direction");u_light_color_=api_.GetUniformLocation(program_,"u_light_color");u_light_intensity_=api_.GetUniformLocation(program_,"u_light_intensity");
s_vp_=api_.GetUniformLocation(skinned_program_,"u_view_projection");s_model_=api_.GetUniformLocation(skinned_program_,"u_model");s_camera_=api_.GetUniformLocation(skinned_program_,"u_camera_position");s_ambient_=api_.GetUniformLocation(skinned_program_,"u_ambient_intensity");s_base_=api_.GetUniformLocation(skinned_program_,"u_base_roughness");s_metal_=api_.GetUniformLocation(skinned_program_,"u_metal_specular");s_emission_=api_.GetUniformLocation(skinned_program_,"u_emission_opacity");s_light_dir_=api_.GetUniformLocation(skinned_program_,"u_light_direction");s_light_color_=api_.GetUniformLocation(skinned_program_,"u_light_color");s_light_intensity_=api_.GetUniformLocation(skinned_program_,"u_light_intensity");s_bones_=api_.GetUniformLocation(skinned_program_,"u_bones[0]");s_bone_count_=api_.GetUniformLocation(skinned_program_,"u_bone_count");
if(u_vp_<0||u_model_<0||u_camera_<0||u_ambient_<0||u_base_<0||u_metal_<0||u_emission_<0||u_light_dir_<0||u_light_color_<0||u_light_intensity_<0||s_vp_<0||s_model_<0||s_camera_<0||s_ambient_<0||s_base_<0||s_metal_<0||s_emission_<0||s_light_dir_<0||s_light_color_<0||s_light_intensity_<0||s_bones_<0||s_bone_count_<0){release();error="OpenGL ES skeletal shader interface mismatch";return false;}return true;}
GpuSubmitResult OpenGLESRenderer::submit(const RenderFrame&frame){GpuSubmitResult out;if(!frame.valid()){out.error="invalid render frame";return out;}if(frame.config.backend!=RenderBackend::OpenGLES){out.error="render frame backend is not OpenGLES";return out;}std::string error;if(!ensure_programs(error)){out.error=std::move(error);return out;}if(frame.config.width==0||frame.config.height==0){out.error="invalid framebuffer dimensions";return out;}api_.Viewport(0,0,static_cast<GlInt>(frame.config.width),static_cast<GlInt>(frame.config.height));const auto sky=frame.lighting.environment.sky_color;api_.ClearColor(sky.r,sky.g,sky.b,1);api_.Clear(GL_COLOR_BUFFER_BIT|GL_DEPTH_BUFFER_BIT);api_.Enable(GL_DEPTH_TEST);api_.DepthFunc(GL_LESS);api_.Enable(GL_CULL_FACE);
std::vector<const RenderDrawCall*>draws;draws.reserve(frame.draws.size());for(const auto&d:frame.draws)draws.push_back(&d);std::stable_sort(draws.begin(),draws.end(),[&](const auto*a,const auto*b){if(a->pass!=b->pass)return a->pass==RenderPass::Opaque;if(a->pass!=RenderPass::Transparent)return a->entity_id<b->entity_id;auto center=[](const Bounds3&x){return Vec3{(x.min.x+x.max.x)*.5f,(x.min.y+x.max.y)*.5f,(x.min.z+x.max.z)*.5f};};auto pa=center(a->world_bounds),pb=center(b->world_bounds);auto da=(pa.x-frame.camera.position.x)*(pa.x-frame.camera.position.x)+(pa.y-frame.camera.position.y)*(pa.y-frame.camera.position.y)+(pa.z-frame.camera.position.z)*(pa.z-frame.camera.position.z);auto db=(pb.x-frame.camera.position.x)*(pb.x-frame.camera.position.x)+(pb.y-frame.camera.position.y)*(pb.y-frame.camera.position.y)+(pb.z-frame.camera.position.z)*(pb.z-frame.camera.position.z);return da>db;});
for(const auto*d:draws){const bool animated=d->animated();const auto&mesh=animated?d->skinned_mesh->indices: d->geometry->parts[d->part_index].mesh.indices;std::vector<float>v;if(animated){v.reserve(d->skinned_mesh->vertices.size()*16);for(const auto&x:d->skinned_mesh->vertices){for(float f:{x.position.x,x.position.y,x.position.z,x.normal.x,x.normal.y,x.normal.z,x.uv.x,x.uv.y})v.push_back(f);for(auto id:x.skin.bones)v.push_back(static_cast<float>(id));for(auto w:x.skin.weights)v.push_back(w);}}else{const auto&m=d->geometry->parts[d->part_index].mesh;v.reserve(m.vertices.size()*8);for(const auto&x:m.vertices)v.insert(v.end(),{x.position.x,x.position.y,x.position.z,x.normal.x,x.normal.y,x.normal.z,x.uv.x,x.uv.y});}
GlUInt vao=0,vbo=0,ibo=0;api_.GenVertexArrays(1,&vao);api_.GenBuffers(1,&vbo);api_.GenBuffers(1,&ibo);if(!vao||!vbo||!ibo){if(vao)api_.DeleteVertexArrays(1,&vao);if(vbo)api_.DeleteBuffers(1,&vbo);if(ibo)api_.DeleteBuffers(1,&ibo);out.error="OpenGL ES buffer allocation failed";return out;}api_.BindVertexArray(vao);api_.BindBuffer(GL_ARRAY_BUFFER,vbo);api_.BufferData(GL_ARRAY_BUFFER,static_cast<GlSize>(v.size()*sizeof(float)),v.data(),GL_STATIC_DRAW);api_.BindBuffer(GL_ELEMENT_ARRAY_BUFFER,ibo);api_.BufferData(GL_ELEMENT_ARRAY_BUFFER,static_cast<GlSize>(mesh.size()*sizeof(GlUInt)),mesh.data(),GL_STATIC_DRAW);const GlInt stride=static_cast<GlInt>((animated?16:8)*sizeof(float));api_.EnableVertexAttribArray(0);api_.VertexAttribPointer(0,3,GL_FLOAT,0,stride,nullptr);api_.EnableVertexAttribArray(1);api_.VertexAttribPointer(1,3,GL_FLOAT,0,stride,reinterpret_cast<const void*>(3*sizeof(float)));api_.EnableVertexAttribArray(2);api_.VertexAttribPointer(2,2,GL_FLOAT,0,stride,reinterpret_cast<const void*>(6*sizeof(float)));if(animated){api_.EnableVertexAttribArray(3);api_.VertexAttribPointer(3,4,GL_FLOAT,0,stride,reinterpret_cast<const void*>(8*sizeof(float)));api_.EnableVertexAttribArray(4);api_.VertexAttribPointer(4,4,GL_FLOAT,0,stride,reinterpret_cast<const void*>(12*sizeof(float)));api_.UseProgram(skinned_program_);api_.UniformMatrix4fv(s_vp_,1,0,frame.view_projection.m.data());api_.UniformMatrix4fv(s_model_,1,0,d->model.m.data());api_.UniformMatrix4fv(s_bones_,static_cast<GlInt>(d->bone_palette.size()),0,reinterpret_cast<const GlFloat*>(d->bone_palette.data()));api_.Uniform1i(s_bone_count_,static_cast<GlInt>(d->bone_palette.size()));api_.Uniform3f(s_camera_,frame.camera.position.x,frame.camera.position.y,frame.camera.position.z);api_.Uniform1f(s_ambient_,std::max(0.0f,frame.lighting.environment.ambient_intensity));api_.Uniform3f(s_light_dir_,0,-1,0);api_.Uniform3f(s_light_color_,1,1,1);api_.Uniform1f(s_light_intensity_,frame.lights.empty()?0:std::max(0.0f,frame.lights.front().intensity));const auto&m=d->material.material;api_.Uniform4f(s_base_,m.base_color.r,m.base_color.g,m.base_color.b,std::clamp(m.roughness,.045f,1.0f));api_.Uniform4f(s_metal_,std::clamp(m.metallic,0.0f,1.0f),std::clamp(m.specular,0.0f,1.0f),0,0);api_.Uniform4f(s_emission_,m.emission.r,m.emission.g,m.emission.b,std::clamp(m.opacity,0.0f,1.0f));}else{api_.UseProgram(program_);api_.UniformMatrix4fv(u_vp_,1,0,frame.view_projection.m.data());api_.UniformMatrix4fv(u_model_,1,0,d->model.m.data());api_.Uniform3f(u_camera_,frame.camera.position.x,frame.camera.position.y,frame.camera.position.z);api_.Uniform1f(u_ambient_,std::max(0.0f,frame.lighting.environment.ambient_intensity));Vec3 ld{0,-1,0};Color3 lc{1,1,1};float li=0;if(!frame.lights.empty()){const auto&l=frame.lights.front();ld=l.direction;lc=l.color;li=l.intensity;}api_.Uniform3f(u_light_dir_,ld.x,ld.y,ld.z);api_.Uniform3f(u_light_color_,lc.r,lc.g,lc.b);api_.Uniform1f(u_light_intensity_,std::max(0.0f,li));const auto&m=d->material.material;api_.Uniform4f(u_base_,m.base_color.r,m.base_color.g,m.base_color.b,std::clamp(m.roughness,.045f,1.0f));api_.Uniform4f(u_metal_,std::clamp(m.metallic,0.0f,1.0f),std::clamp(m.specular,0.0f,1.0f),0,0);api_.Uniform4f(u_emission_,m.emission.r,m.emission.g,m.emission.b,std::clamp(m.opacity,0.0f,1.0f));}
if(d->pass==RenderPass::Transparent){api_.Enable(GL_BLEND);api_.BlendFunc(GL_SRC_ALPHA,GL_ONE_MINUS_SRC_ALPHA);}else api_.Disable(GL_BLEND);api_.DrawElements(GL_TRIANGLES,static_cast<GlInt>(mesh.size()),GL_UNSIGNED_INT,nullptr);api_.DeleteBuffers(1,&vbo);api_.DeleteBuffers(1,&ibo);api_.DeleteVertexArrays(1,&vao);++out.draw_calls;out.triangles+=mesh.size()/3;if(animated)++out.animated_draw_calls;}
api_.Disable(GL_BLEND);api_.Disable(GL_CULL_FACE);out.success=true;return out;}
void OpenGLESRenderer::release()noexcept{if(program_&&api_.DeleteProgram)api_.DeleteProgram(program_);if(skinned_program_&&api_.DeleteProgram)api_.DeleteProgram(skinned_program_);program_=skinned_program_=0;u_vp_=u_model_=u_camera_=u_ambient_=u_base_=u_rough_=u_metal_=u_emission_=u_opacity_=u_light_dir_=u_light_color_=u_light_intensity_=-1;s_vp_=s_model_=s_camera_=s_ambient_=s_base_=s_metal_=s_emission_=s_light_dir_=s_light_color_=s_light_intensity_=s_bones_=s_bone_count_=-1;}
